<?php require_once __DIR__.'/includes/bootstrap.php';require_login();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$items=json_decode($_POST['cart_json']??'[]',true);if(!$items)$error='سبد خرید خالی است.';else{try{$pdo->beginTransaction();$total=0;$valid=[];foreach($items as $it){$st=$pdo->prepare("SELECT id,name,price,stock FROM products WHERE id=? AND is_active=1 FOR UPDATE");$st->execute([(int)$it['id']]);$p=$st->fetch();$qty=max(1,(int)$it['qty']);if(!$p||$p['stock']<$qty)throw new Exception('موجودی یکی از محصولات کافی نیست.');$total+=$p['price']*$qty;$valid[]=[$p,$qty];}$st=$pdo->prepare("INSERT INTO orders(user_id,total_amount,status,shipping_name,shipping_phone,shipping_address) VALUES(?,?, 'pending',?,?,?)");$st->execute([$_SESSION['user']['id'],$total,trim($_POST['name']),trim($_POST['phone']),trim($_POST['address'])]);$oid=$pdo->lastInsertId();foreach($valid as [$p,$qty]){$pdo->prepare("INSERT INTO order_items(order_id,product_id,quantity,unit_price) VALUES(?,?,?,?)")->execute([$oid,$p['id'],$qty,$p['price']]);$pdo->prepare("UPDATE products SET stock=stock-? WHERE id=?")->execute([$qty,$p['id']]);}$pdo->commit();header('Location: orders.php?success=1');exit;}catch(Exception $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}}
$pageTitle='ثبت سفارش';include __DIR__.'/includes/header.php';?>
<main class="page-content"><form class="form-wrap" method="post" id="checkout-form"><h1>اطلاعات ارسال سفارش</h1><?php if($error):?><p class="notice"><?=e($error)?></p><?php endif;?><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="cart_json" id="cart-json"><div class="field"><label>نام تحویل‌گیرنده</label><input name="name" required value="<?=e($_SESSION['user']['name'])?>"></div><div class="field"><label>شماره تماس</label><input name="phone" required></div><div class="field"><label>نشانی کامل</label><textarea name="address" required></textarea></div><p class="notice">این نسخه، سفارش را در پایگاه داده ثبت می‌کند؛ اتصال درگاه پرداخت آنلاین نیازمند اطلاعات پذیرنده است.</p><button>ثبت نهایی سفارش</button></form></main><script>document.getElementById('checkout-form').addEventListener('submit',()=>document.getElementById('cart-json').value=localStorage.getItem('rosea_cart')||'[]');</script><?php include __DIR__.'/includes/footer.php';?>
